```python
# EVOLVE-BLOCK-START
CPP_CODE = '''
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

double rand_double(double L, double U) {
    return L + (U - L) * rand() / RAND_MAX;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N = 10, L = 4, T = 500;
    ll K;
    cin >> N >> L >> T >> K;

    vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    vector<vector<ll>> C(L, vector<ll>(N));
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> C[i][j];
        }
    }

    vector<vector<ll>> B(L, vector<ll>(N, 1));
    vector<vector<ll>> P(L, vector<ll>(N, 0));
    ll apples = K;

    auto simulate_with_policy = [&](int start_turn, vector<vector<ll>> B_local, vector<vector<ll>> P_local, ll apples_local, int policy) -> ll {
        // Policy variants:
        // 0: Early L0 Builder
        // 1: Aggressive L3
        // 2: Conservative L3 (threshold 5000)
        // 3: Balanced Cascade

        for (int t = start_turn; t < T; ++t) {
            vector<pair<int, int>> candidates;

            if (policy == 0) { // Early L0 Builder
                if (apples_local < 500) {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[0][j] * (P_local[0][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(0, j);
                        }
                    }
                } else {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[3][j] * (P_local[3][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(3, j);
                        }
                    }
                }
            }
            else if (policy == 1) { // Aggressive L3
                for (int j = 0; j < N; ++j) {
                    ll cost = C[3][j] * (P_local[3][j] + 1);
                    if (apples_local >= cost) {
                        candidates.emplace_back(3, j);
                    }
                }
                // If no L3 affordable, fall back to L0
                if (candidates.empty()) {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[0][j] * (P_local[0][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(0, j);
                        }
                    }
                }
            }
            else if (policy == 2) { // Conservative L3 (high threshold)
                if (apples_local >= 5000) {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[3][j] * (P_local[3][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(3, j);
                        }
                    }
                } else {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[0][j] * (P_local[0][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(0, j);
                        }
                    }
                }
            }
            else if (policy == 3) { // Balanced Cascade
                if (rand_double(0, 1) < 0.5) {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[0][j] * (P_local[0][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(0, j);
                        }
                    }
                } else {
                    for (int j = 0; j < N; ++j) {
                        ll cost = C[3][j] * (P_local[3][j] + 1);
                        if (apples_local >= cost) {
                            candidates.emplace_back(3, j);
                        }
                    }
                }
            }

            // Apply one action if possible
            if (!candidates.empty()) {
                auto [i, j] = candidates[0];
                ll cost = C[i][j] * (P_local[i][j] + 1);
                if (apples_local >= cost) {
                    apples_local -= cost;
                    P_local[i][j]++;
                }
            }

            // Cascade phase
            for (int i = 0; i < L; ++i) {
                if (i == 0) {
                    for (int j = 0; j < N; ++j) {
                        apples_local += (ll)A[j] * B_local[i][j] * P_local[i][j];
                    }
                } else {
                    for (int j = 0; j < N; ++j) {
                        B_local[i-1][j] += B_local[i][j] * P_local[i][j];
                    }
                }
            }
        }
        return apples_local;
    };

    vector<string> actions(T);

    for (int t = 0; t < T; ++t) {
        vector<pair<pair<int, int>, double>> candidates;

        // Prune to top 20 actions using heuristic
        for (int i = 0; i < L; ++i) {
            for (int j = 0; j < N; ++j) {
                ll cost = C[i][j] * (P[i][j] + 1);
                if (apples >= cost) {
                    double score = 0;
                    if (i == 0) score = (double)A[j] / cost;
                    else if (i == 3) score = (double)1e6 / cost; // High potential
                    else score = (double)1 / cost;
                    candidates.emplace_back(make_pair(i, j), score);
                }
            }
        }

        // Sort and take top 20
        sort(candidates.begin(), candidates.end(), [](auto &a, auto &b) {
            return a.second > b.second;
        });
        if (candidates.size() > 20) candidates.resize(20);

        ll best_final = apples;
        pair<int, int> best_action = {-1, -1};

        // Test doing nothing
        {
            auto B_copy = B;
            auto P_copy = P;
            ll sim_apples = apples;
            // Try each policy for the "do nothing" action
            for (int policy = 0; policy < 4; ++policy) {
                ll final_apples = simulate_with_policy(t+1, B_copy, P_copy, sim_apples, policy);
                if (final_apples > best_final) {
                    best_final = final_apples;
                    best_action = {-1, -1};
                }
            }
        }

        // Test each candidate action with multi-policy simulation
        for (auto &cand : candidates) {
            int i = cand.first.first;
            int j = cand.first.second;
            ll cost = C[i][j] * (P[i][j] + 1);
            if (apples < cost) continue;

            auto B_copy = B;
            auto P_copy = P;
            ll sim_apples = apples;

            // Apply action
            sim_apples -= cost;
            P_copy[i][j]++;

            // Cascade after action
            for (int lvl = 0; lvl < L; ++lvl) {
                if (lvl == 0) {
                    for (int jj = 0; jj < N; ++jj) {
                        sim_apples += (ll)A[jj] * B_copy[lvl][jj] * P_copy[lvl][jj];
                    }
                } else {
                    for (int jj = 0; jj < N; ++jj) {
                        B_copy[lvl-1][jj] += B_copy[lvl][jj] * P_copy[lvl][jj];
                    }
                }
            }

            // Try each policy variant for the rest of the simulation
            ll best_policy_result = sim_apples;
            for (int policy = 0; policy < 4; ++policy) {
                ll final_apples = simulate_with_policy(t+1, B_copy, P_copy, sim_apples, policy);
                if (final_apples > best_policy_result) {
                    best_policy_result = final_apples;
                }
            }

            if (best_policy_result > best_final) {
                best_final = best_policy_result;
                best_action = {i, j};
            }
        }

        // Execute best action
        if (best_action.first == -1) {
            actions[t] = "-1";
        } else {
            int i = best_action.first;
